      "捞起肋排用温水冲洗干净，沥干水分，备用。",
      "准备所需材料，用了一点自己酿的石榴酒，其实用黄酒比较好。冰糖提前放保鲜袋里用擀面杖轻轻敲碎。喜欢桂皮或者香叶的味道也可以加点，我个人不太喜欢加太多香料，只用了八角。",
