    "steps": [
      "生菜择去黄叶，一片片掰开，清洗干净沥水。大蒜剁成蒜末。在一只碗里加少许盐、一勺蚝油、一勺生抽、少许白糖、一勺淀粉，加适量清水拌匀待用。",
      "烧锅开水，水开后加少许盐、两滴油，将生菜下入焯约一分钟。",
      "生菜捞出控水 摆盘。",
      "锅里放适量油，烧热后把蒜末下入炒香。",
      "淋入先前调好的味汁，开小火，用锅铲转圈搅动，至浓稠起芡时关火。把锅内芡汁均匀淋在生菜上即可。",
      "成品图。",
      "清淡鲜甜，别有滋味。"
    ],
    "note": ""
