    "steps": [
      "准备食材。",
      "里脊肉切细丝加入1勺葱姜料酒去腥。",
      "再加入适量盐和少量淀粉抓拌均匀，腌制10分钟。",
      "葱白和黄瓜切丝，豆腐皮切方块焯水后摆入盘中。",
      "起锅烧油，倒入腌好的肉丝。",
      "迅速划散翻炒至变色。",
      "加入2勺甜面酱。",
      "中火翻炒至每一根肉丝都包裹上酱汁。",
      "将炒好的肉丝装盘。",
      "一道色香味俱全的京酱肉丝就做好啦！"
    ],
