      "整理成一个光滑的面团放在抹了油的容器里盖上保鲜膜温暖处发酵到两倍大。",
      "我用烤箱发酵功能30度大概发酵了一小时，发酵到两倍大的面团手指沾面粉戳一个洞不回缩或者缓慢回缩就是发酵好了。",
      "平均分成八份搓圆，盖上保鲜膜松弛二十分钟。",
      "现在开始整形，取一个松弛好的面团，光滑面朝上，擀成长方形。",
      "翻过来光滑面朝下，长边卷起来，卷两下。",
      "另一边也一样操作。"
