      "顺一个方向搅拌上劲儿，如果感觉稀了可以在搅拌时加上一些淀粉。",
      "团成丸子，放入空气炸锅，先设定200度，5分钟，让丸子定型，打开锅晃一晃，让丸子翻转。再200度，炸8分钟。",
      "出锅！油已经被炸出去了，吃着很健康。"
