    "note": "诗心片语：\n1：碗中的清水不要加多了，多了的话需要加入的面粉就多，那样煎出来的饼就不够香。如果立即操作，也可直接把土豆刨成丝，然后加入鸡蛋。\n2：摊饼之前，锅不要烧得太热，太热了，饼糊一下锅就熟，便不会流动，也就较难摊平。\n3：刚下锅时铺平以后不要动，底部煎熟以后，只要晃动锅，饼会自己离开锅底。\n4：这样的土豆饼煎至两面稍微焦黄的会更香。"
