      "放入切好的香菇",
      "再翻炒几下",
      "依次倒入米酒、料酒、老抽、食盐",
      "再放入两颗熟鸡蛋，进行焖煮",
      "煮至汤汁浓稠，香味四溢即可",
      "煮些青菜，浇上卤肉汁，把鸡蛋切开，台湾卤肉饭完成！"
