      "干辣椒剪成小段、蒜切片。",
      "锅中猪油热后，关小火。",
      "放入花椒粒爆香，再放入蒜片、干辣椒。",
      "小火煸出香味后下入包菜，转大火。",
      "炒至变色，调入老抽1/3勺翻炒均匀。",
      "调入少许盐、醋炒匀，即可关火。"
